arguments.command:
python3 -c "
import parse
text = '''
            letters: abcdef_GHIJLK
            non-letters: !@#%$ *^%
            whitespace: \"   \\t\\n\"
            non-whitespace: \\tabc\\n
            digits: 0xabcdef
            non-digits: abcdef
            numbers with thousands: 1.000.000
            fixed-point: 0.00001
            floating-point: NAN
            general numbers: 1.1e10 nan
            binary: 0B1000
            octal: 0O1000
            hex: 0X1000
            ISO 8601 e.g. 1972-01-20T10:21:36Z
            RFC2822 e.g. Mon, 20 Jan 1972 10:21:36 +1000
            Global e.g. 20/1/1972 10:21:36 AM +1:00
            US e.g. 1/20/1972 10:21:36 PM +10:30
            ctime() e.g. Sun Sep 16 01:03:52 1973
            HTTP e.g. 21/Nov/2011:00:07:11 +0000
            time: 10:21:36 PM -5:30
            final value: spam
        '''

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{s}\"
            non-whitespace: \\t{S}\\n
            digits: {d}
            non-digits: {D}
            numbers with thousands: {n}
            fixed-point: {f}
            floating-point: {e}
            general numbers: {g} {g}
            binary: {b}
            octal: {o}
            hex: {x}
            ISO 8601 e.g. {ti}
            RFC2822 e.g. {te}
            Global e.g. {tg}
            US e.g. {ta}
            ctime() e.g. {tc}
            HTTP e.g. {th}
            time: {tt}
            final value: {}
        '''

r = parse.parse(fmt, text)
print(r)
" 2>/dev/null
